@Configuration
public class ReactivacionFlowConfig {

    @Bean
    Flow reactivacion(Step abreListados, GeneracionDominicalDecider dominical,
                      Step pendientesB51, Step generaArchivos, Step finReactiva) {
        return new FlowBuilder<Flow>("reactivacion")
            .start(abreListados)                                    // 90001000-ABRE-ARCH-LIST
            .next(dominical).on("GENERA").to(pendientesB51)         // 90002000 + 90002200-SORT-PTE
                .next(generaArchivos)                               // I03 (S500), E01 (S084), E02 (S087), I04
                .next(finReactiva)
            .from(dominical).on("*").to(finReactiva)                // 90005000-FIN-REACTIVA siempre
            .build();
    }
}
